 assumptions=json.loads((ROOT/'scenarios/muscle_prediction_assumptions.json').read_text(encoding='utf-8'));audit=json.loads((OUT/'vertical/acceleration_2400hz/muscle_operating_audit.json').read_text(encoding='utf-8'));numerical=json.loads((OUT/'vertical/acceleration_2400hz/verification.json').read_text(encoding='utf-8'))
