  for key,path in [('solver_sha256',ROOT/'scripts/tension_reference.py'),('script_sha256',ROOT/'scripts/build_tension_reference.py'),('configuration_sha256',ROOT/'scenarios/tension_reference.json')]:draft_available=draft_available and recorded.get(key)==hashlib.sha256(path.read_bytes()).hexdigest()
