 gates={'vertical_rigid_body_numerical_checks':numerical['numerical_consistency_passed'],'muscle_moment_arm_derivatives_consistent':derivative['status']=='passed','sampled_nonnegative_force_existence':audit['all_sampled_frames_force_feasible'],'unbounded_tension_solver_fixtures':solver_ok,'sampled_GH_stable_tension_history_computed':draft_available,'muscle_operating_length_mapping_consistent':audit['biological_operating_range_gate_passed'],'major_muscle_connectivity_complete':len(audit['missing_major_groups'])==0,'continuous_task_motion_ready':False}
